python3 - <<'EOF'
import json
d = json.load(open('bench/results/2026-10-12/m1-ngram/recon/inventory.json'))
print(type(d), list(d.keys()) if isinstance(d, dict) else len(d))
def summarize(records):
    from collections import defaultdict
    agg = defaultdict(list)
    for r in records:
        key = (r.get('role'), r.get('step'))
        agg[key].append(r)
    for k in sorted(agg, key=lambda x: (x[0], x[1])):
        rows = agg[k]
        tot = { 'prompt_n': sum(r.get('prompt_n',0) for r in rows),
                'cache_n': sum(r.get('cache_n',0) for r in rows),
                'predicted_n': sum(r.get('predicted_n',0) for r in rows)}
        print(k, len(rows), tot)
if 'tap_records' in d:
    summarize(d['tap_records'])
elif 'records' in d:
    summarize(d['records'])
else:
    print(d)
EOF

